import React, { useState } from 'react';
import '../contact/Contact.css';
import { Form, Col, Row, Button } from 'react-bootstrap';
const ContactForm = () => {
  // Use the useState hook to create state variables for the form fields
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [modalOpen, setModalOpen] = useState(false);

  // Handle form submission
  const handleSubmit = (event) => {
    event.preventDefault();
    // Validate the form fields
    if (firstName === '' || lastName === '' || email === '' || message === '') {
      // Display an error message if any of the fields are empty
      alert('All fields are required');
      return;
    }
    // If the form is valid, open the modal
    setModalOpen(true);
  }

  return (
    <Form className="container border border-primary border-2 rounded-3 col-lg-7 col-11 mt-auto p-2 text-white bg-info bg-opacity-10" onSubmit={handleSubmit}>
      {/* Render the form fields */}
      <Form.Group as={Col} controlId="firstName">
        <Form.Label>First Name</Form.Label>
        <Form.Control type="text" placeholder="First Name" value={firstName} onChange={(event) => setFirstName(event.target.value)} />
      </Form.Group>
        <Form.Group as={Col} controlId="lastName">
        <Form.Label>Last Name</Form.Label>
        <Form.Control type="text" placeholder="Last Name" value={lastName} onChange={(event) => setLastName(event.target.value)} />
      </Form.Group>
      <br />
      <Form.Group className="mb-3" controlId="email">
        <Form.Label>Email</Form.Label>
        <input type="email" value={email} onChange={(event) => setEmail(event.target.value)} />
      </Form.Group>
      <br />
      <label>
        Message:
        <textarea value={message} onChange={(event) => setMessage(event.target.value)} />
      </label>
      <br />
      <button type="submit">Send</button>
      {/* Render the modal if it is open */}
      {modalOpen && (
        <div className="modal">
          <div className="modal-content">
            <p>Your message has been sent!</p>
            <button onClick={() => setModalOpen(false)}>Close</button>
          </div>
        </div>
      )}
    </Form>
  );
}

export default ContactForm;
